{
  "name": "Evo - Ton Compagnon de Réussite",
  "description": "Une application de productivité tout-en-un conçue pour les élèves et étudiants : Todo List intelligente, Matrice d'Eisenhower, Timer Pomodoro et suivi de progression personnalisé.",
  "requestFramePermissions": [
    "notifications"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum TaskStatus {
  TODO = 'todo',
  IN_PROGRESS = 'in_progress',
  DONE = 'done'
}

export enum TaskPriority {
  LOW = 'low',
  MEDIUM = 'medium',
  HIGH = 'high'
}

export enum EisenhowerQuadrant {
  DO_FIRST = 'do_first',      // Urgent & Important
  SCHEDULE = 'schedule',      // Not Urgent & Important
  DELEGATE = 'delegate',      // Urgent & Not Important
  ELIMINATE = 'eliminate'     // Not Urgent & Not Important
}

export interface Task {
  id: string;
  title: string;
  description?: string;
  status: TaskStatus;
  priority: TaskPriority;
  quadrant: EisenhowerQuadrant;
  dueDate?: string;
  estimatedMinutes: number;
  actualMinutes: number;
  createdAt: number;
}

export type ThemeType = 'lime' | 'blue' | 'purple' | 'dark';

export interface AppState {
  tasks: Task[];
  theme: ThemeType;
  pomodoroConfig: {
    workTime: number;
    shortBreak: number;
    longBreak: number;
  };
}

import React from 'react';
import { ThemeType } from './types';

export const THEMES: Record<ThemeType, { 
  primary: string; 
  secondary: string; 
  bg: string; 
  accent: string;
  text: string;
  card: string;
}> = {
  lime: {
    primary: 'bg-lime-500',
    secondary: 'text-lime-600',
    bg: 'bg-slate-50',
    accent: 'border-lime-200',
    text: 'text-slate-900',
    card: 'bg-white'
  },
  blue: {
    primary: 'bg-blue-600',
    secondary: 'text-blue-700',
    bg: 'bg-slate-50',
    accent: 'border-blue-200',
    text: 'text-slate-900',
    card: 'bg-white'
  },
  purple: {
    primary: 'bg-purple-600',
    secondary: 'text-purple-700',
    bg: 'bg-slate-50',
    accent: 'border-purple-200',
    text: 'text-slate-900',
    card: 'bg-white'
  },
  dark: {
    primary: 'bg-indigo-500',
    secondary: 'text-indigo-400',
    bg: 'bg-slate-950',
    accent: 'border-slate-800',
    text: 'text-slate-100',
    card: 'bg-slate-900'
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  CheckSquare, 
  Grid2X2, 
  Timer, 
  BarChart3, 
  Settings,
  Plus,
  Search,
  Moon,
  Sun,
  Palette
} from 'lucide-react';
import { Task, TaskStatus, TaskPriority, EisenhowerQuadrant, ThemeType } from './types';
import { THEMES } from './constants';
import Dashboard from './components/Dashboard';
import TodoList from './components/Tasks/TodoList';
import EisenhowerMatrix from './components/Matrix/EisenhowerMatrix';
import Pomodoro from './components/Focus/Pomodoro';
import ProgressTracking from './components/Stats/ProgressTracking';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [tasks, setTasks] = useState<Task[]>([]);
  const [theme, setTheme] = useState<ThemeType>('lime');

  // Persist tasks and theme to localStorage
  useEffect(() => {
    const savedTasks = localStorage.getItem('evo_tasks');
    const savedTheme = localStorage.getItem('evo_theme');
    if (savedTasks) setTasks(JSON.parse(savedTasks));
    if (savedTheme) setTheme(savedTheme as ThemeType);
  }, []);

  useEffect(() => {
    localStorage.setItem('evo_tasks', JSON.stringify(tasks));
    localStorage.setItem('evo_theme', theme);

    // Apply dark mode class to body for global styles
    if (theme === 'dark') {
      document.body.classList.add('dark');
      document.body.style.backgroundColor = '#020617';
    } else {
      document.body.classList.remove('dark');
      document.body.style.backgroundColor = '#f8fafc';
    }
  }, [tasks, theme]);

  const addTask = (task: Omit<Task, 'id' | 'createdAt' | 'actualMinutes'>) => {
    const newTask: Task = {
      ...task,
      id: Math.random().toString(36).substr(2, 9),
      createdAt: Date.now(),
      actualMinutes: 0
    };
    setTasks([...tasks, newTask]);
  };

  const updateTask = (id: string, updates: Partial<Task>) => {
    setTasks(tasks.map(t => t.id === id ? { ...t, ...updates } : t));
  };

  const deleteTask = (id: string) => {
    setTasks(tasks.filter(t => t.id !== id));
  };

  const currentTheme = THEMES[theme];

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard tasks={tasks} theme={theme} onAddTask={addTask} onUpdateTask={updateTask} />;
      case 'tasks':
        return <TodoList tasks={tasks} onUpdateTask={updateTask} onDeleteTask={deleteTask} onAddTask={addTask} theme={theme} />;
      case 'matrix':
        return <EisenhowerMatrix tasks={tasks} onUpdateTask={updateTask} theme={theme} />;
      case 'focus':
        return <Pomodoro theme={theme} tasks={tasks} onUpdateTask={updateTask} />;
      case 'stats':
        return <ProgressTracking tasks={tasks} theme={theme} />;
      default:
        return <Dashboard tasks={tasks} theme={theme} onAddTask={addTask} onUpdateTask={updateTask} />;
    }
  };

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
    { id: 'tasks', label: 'Tâches', icon: CheckSquare },
    { id: 'matrix', label: 'Matrice', icon: Grid2X2 },
    { id: 'focus', label: 'Focus', icon: Timer },
    { id: 'stats', label: 'Progrès', icon: BarChart3 },
  ];

  return (
    <div className={`min-h-screen flex flex-col md:flex-row ${currentTheme.bg} ${currentTheme.text} transition-colors duration-300`}>
      {/* Sidebar - Desktop */}
      <aside className={`hidden md:flex flex-col w-64 ${currentTheme.card} border-r ${currentTheme.accent} h-screen sticky top-0`}>
        <div className="p-6 flex items-center gap-3">
          <div className={`w-10 h-10 rounded-xl ${currentTheme.primary} flex items-center justify-center text-white shadow-lg`}>
            <BarChart3 size={24} />
          </div>
          <span className="text-2xl font-bold tracking-tight">Evo</span>
        </div>

        <nav className="flex-1 px-4 space-y-2 mt-4">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-200 ${
                activeTab === item.id 
                ? `${currentTheme.primary} text-white shadow-md` 
                : `hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-500 dark:text-slate-400`
              }`}
            >
              <item.icon size={20} />
              <span className="font-medium">{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="p-4 border-t border-slate-100 dark:border-slate-800">
          <div className="flex justify-between items-center mb-4 px-2">
            <span className="text-sm font-semibold text-slate-400">THÈME</span>
            <div className="flex gap-1">
              {(Object.keys(THEMES) as ThemeType[]).map((t) => (
                <button
                  key={t}
                  onClick={() => setTheme(t)}
                  className={`w-6 h-6 rounded-full border-2 ${
                    theme === t ? 'border-slate-400' : 'border-transparent'
                  } ${THEMES[t].primary}`}
                  title={t}
                />
              ))}
            </div>
          </div>
          <div className="bg-slate-50 dark:bg-slate-800 p-3 rounded-xl flex items-center gap-3">
            <div className={`w-8 h-8 rounded-lg ${currentTheme.primary} opacity-20`} />
            <div className="flex-1">
              <p className="text-xs font-bold truncate">Utilisateur Démo</p>
              <p className="text-[10px] text-slate-400">Élève Premium</p>
            </div>
          </div>
        </div>
      </aside>

      {/* Mobile Nav */}
      <nav className={`md:hidden fixed bottom-0 left-0 right-0 z-50 ${currentTheme.card} border-t ${currentTheme.accent} px-2 py-3 flex justify-around items-center shadow-2xl`}>
        {navItems.map((item) => (
          <button
            key={item.id}
            onClick={() => setActiveTab(item.id)}
            className={`flex flex-col items-center gap-1 p-2 rounded-lg transition-colors ${
              activeTab === item.id ? currentTheme.secondary : 'text-slate-400'
            }`}
          >
            <item.icon size={20} />
            <span className="text-[10px] font-medium">{item.label}</span>
          </button>
        ))}
      </nav>

      {/* Main Content */}
      <main className="flex-1 flex flex-col p-4 md:p-8 pb-24 md:pb-8 overflow-y-auto max-w-7xl mx-auto w-full">
        <header className="flex justify-between items-center mb-8">
          <div>
            <h1 className="text-2xl md:text-3xl font-bold">Bonjour ! 👋</h1>
            <p className="text-slate-500 dark:text-slate-400 text-sm md:text-base">Prêt pour une session de travail efficace ?</p>
          </div>
          <div className="flex items-center gap-4">
            <button className={`p-2 rounded-xl border ${currentTheme.accent} hover:bg-white dark:hover:bg-slate-800 transition-colors`}>
              <Search size={20} />
            </button>
          </div>
        </header>

        {renderContent()}
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import { Task, TaskStatus, ThemeType } from '../types';
import { THEMES } from '../constants';
import { CheckCircle2, Clock, Calendar, TrendingUp, Plus } from 'lucide-react';

interface DashboardProps {
  tasks: Task[];
  theme: ThemeType;
  onAddTask: (task: any) => void;
  onUpdateTask: (id: string, updates: any) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ tasks, theme, onAddTask, onUpdateTask }) => {
  const currentTheme = THEMES[theme];

  const completedTasks = tasks.filter(t => t.status === TaskStatus.DONE);
  const pendingTasks = tasks.filter(t => t.status !== TaskStatus.DONE);
  const totalEstimated = tasks.reduce((acc, curr) => acc + curr.estimatedMinutes, 0);
  const progressPercentage = tasks.length > 0 ? Math.round((completedTasks.length / tasks.length) * 100) : 0;

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      {/* Stats Overview */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard 
          label="Tâches terminées" 
          value={completedTasks.length.toString()} 
          icon={CheckCircle2} 
          color="text-green-500" 
          theme={theme}
        />
        <StatCard 
          label="Tâches en attente" 
          value={pendingTasks.length.toString()} 
          icon={Clock} 
          color="text-orange-500" 
          theme={theme}
        />
        <StatCard 
          label="Temps de travail total" 
          value={`${Math.floor(totalEstimated / 60)}h ${totalEstimated % 60}m`} 
          icon={Calendar} 
          color="text-blue-500" 
          theme={theme}
        />
        <StatCard 
          label="Score de Focus" 
          value={`${progressPercentage}%`} 
          icon={TrendingUp} 
          color="text-purple-500" 
          theme={theme}
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Main Progression Card */}
        <div className={`lg:col-span-2 ${currentTheme.card} rounded-3xl p-8 border ${currentTheme.accent} shadow-sm flex flex-col items-center justify-center min-h-[300px]`}>
           <div className="relative w-48 h-48 flex items-center justify-center">
              <svg className="w-full h-full transform -rotate-90">
                <circle
                  cx="96"
                  cy="96"
                  r="80"
                  stroke="currentColor"
                  strokeWidth="12"
                  fill="transparent"
                  className="text-slate-100 dark:text-slate-800"
                />
                <circle
                  cx="96"
                  cy="96"
                  r="80"
                  stroke="currentColor"
                  strokeWidth="12"
                  fill="transparent"
                  strokeDasharray={2 * Math.PI * 80}
                  strokeDashoffset={2 * Math.PI * 80 * (1 - progressPercentage / 100)}
                  strokeLinecap="round"
                  className={`${currentTheme.secondary} transition-all duration-1000 ease-out`}
                />
              </svg>
              <div className="absolute flex flex-col items-center">
                <span className="text-4xl font-extrabold">{progressPercentage}%</span>
                <span className="text-xs text-slate-400 font-medium uppercase tracking-widest">Progress</span>
              </div>
           </div>
           <div className="mt-8 text-center">
              <h3 className="text-xl font-bold mb-2">Ton objectif du jour</h3>
              <p className="text-slate-500 max-w-xs mx-auto text-sm italic">
                {progressPercentage === 100 
                  ? "Félicitations ! Tu as accompli toutes tes tâches aujourd'hui. 🏆" 
                  : progressPercentage > 50 
                  ? "Tu es sur la bonne voie ! Continue tes efforts. 💪" 
                  : "Une petite tâche à la fois, tu vas y arriver ! 🚀"}
              </p>
           </div>
        </div>

        {/* Quick Task Add */}
        <div className={`flex flex-col gap-4`}>
          <div className={`${currentTheme.card} rounded-3xl p-6 border ${currentTheme.accent} shadow-sm flex-1`}>
            <h3 className="font-bold text-lg mb-4 flex items-center gap-2">
              <Plus size={20} className={currentTheme.secondary} />
              Ajout Rapide
            </h3>
            <form onSubmit={(e) => {
              e.preventDefault();
              const form = e.target as HTMLFormElement;
              const input = form.elements.namedItem('taskTitle') as HTMLInputElement;
              if (input.value.trim()) {
                onAddTask({
                  title: input.value,
                  status: TaskStatus.TODO,
                  priority: TaskPriority.MEDIUM,
                  quadrant: EisenhowerQuadrant.DO_FIRST,
                  estimatedMinutes: 30
                });
                form.reset();
              }
            }} className="space-y-4">
              <input 
                name="taskTitle"
                type="text" 
                placeholder="Quelle est la prochaine étape ?"
                className={`w-full bg-slate-50 dark:bg-slate-800 border-none rounded-xl px-4 py-3 text-sm focus:ring-2 ring-lime-500 transition-all`}
              />
              <button className={`w-full ${currentTheme.primary} text-white font-bold py-3 rounded-xl shadow-lg hover:opacity-90 transition-all transform active:scale-95`}>
                Ajouter à ma liste
              </button>
            </form>
          </div>

          <div className={`${currentTheme.card} rounded-3xl p-6 border ${currentTheme.accent} shadow-sm`}>
            <h3 className="font-bold text-lg mb-2">Conseil de l'IA Evo 🤖</h3>
            <p className="text-sm text-slate-500 leading-relaxed">
              Priorise tes révisions de Mathématiques le matin quand ton cerveau est le plus réceptif.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

const StatCard: React.FC<{ label: string; value: string; icon: any; color: string; theme: ThemeType }> = ({ label, value, icon: Icon, color, theme }) => {
  const currentTheme = THEMES[theme];
  return (
    <div className={`${currentTheme.card} rounded-2xl p-4 border ${currentTheme.accent} shadow-sm flex items-center gap-4`}>
      <div className={`p-3 rounded-xl bg-slate-50 dark:bg-slate-800 ${color}`}>
        <Icon size={24} />
      </div>
      <div>
        <p className="text-xs text-slate-400 font-medium">{label}</p>
        <p className="text-lg font-bold">{value}</p>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Task, TaskStatus, TaskPriority, EisenhowerQuadrant, ThemeType } from '../../types';
import { THEMES } from '../../constants';
import { Trash2, CheckCircle2, Circle, MoreVertical, Plus, Filter, Clock } from 'lucide-react';

interface TodoListProps {
  tasks: Task[];
  onUpdateTask: (id: string, updates: Partial<Task>) => void;
  onDeleteTask: (id: string) => void;
  onAddTask: (task: any) => void;
  theme: ThemeType;
}

const TodoList: React.FC<TodoListProps> = ({ tasks, onUpdateTask, onDeleteTask, onAddTask, theme }) => {
  const [filter, setFilter] = useState<TaskStatus | 'all'>('all');
  const currentTheme = THEMES[theme];

  const filteredTasks = tasks.filter(t => filter === 'all' || t.status === filter);

  const toggleStatus = (task: Task) => {
    const nextStatus = task.status === TaskStatus.DONE ? TaskStatus.TODO : TaskStatus.DONE;
    onUpdateTask(task.id, { status: nextStatus });
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div className="flex gap-2">
          {(['all', TaskStatus.TODO, TaskStatus.DONE] as const).map(f => (
            <button
              key={f}
              onClick={() => setFilter(f)}
              className={`px-4 py-2 rounded-full text-sm font-medium transition-all ${
                filter === f 
                ? `${currentTheme.primary} text-white` 
                : 'bg-white dark:bg-slate-800 text-slate-500 border border-slate-200 dark:border-slate-800'
              }`}
            >
              {f === 'all' ? 'Tous' : f === TaskStatus.TODO ? 'À faire' : 'Terminé'}
            </button>
          ))}
        </div>
        <button 
          onClick={() => {
            const title = prompt("Titre de la tâche ?");
            if (title) onAddTask({ 
              title, 
              status: TaskStatus.TODO, 
              priority: TaskPriority.MEDIUM, 
              quadrant: EisenhowerQuadrant.DO_FIRST,
              estimatedMinutes: 30 
            });
          }}
          className={`${currentTheme.primary} text-white px-6 py-2 rounded-xl flex items-center gap-2 shadow-lg hover:opacity-90 transition-all`}
        >
          <Plus size={18} /> Nouvelle tâche
        </button>
      </div>

      <div className="space-y-3">
        {filteredTasks.length === 0 ? (
          <div className="text-center py-20 bg-white/50 dark:bg-slate-900/50 rounded-3xl border border-dashed border-slate-300 dark:border-slate-800">
            <p className="text-slate-400">Aucune tâche trouvée. Profite de ce temps libre ! ✨</p>
          </div>
        ) : (
          filteredTasks.map(task => (
            <div 
              key={task.id} 
              className={`group ${currentTheme.card} border ${currentTheme.accent} p-4 rounded-2xl flex items-center gap-4 shadow-sm hover:shadow-md transition-all animate-in slide-in-from-left-2`}
            >
              <button 
                onClick={() => toggleStatus(task)}
                className={`transition-colors ${task.status === TaskStatus.DONE ? 'text-green-500' : 'text-slate-300 hover:text-slate-400'}`}
              >
                {task.status === TaskStatus.DONE ? <CheckCircle2 size={24} /> : <Circle size={24} />}
              </button>

              <div className="flex-1">
                <h4 className={`font-semibold ${task.status === TaskStatus.DONE ? 'line-through text-slate-400' : ''}`}>
                  {task.title}
                </h4>
                <div className="flex items-center gap-3 mt-1">
                  <span className={`text-[10px] uppercase font-bold px-2 py-0.5 rounded-md ${
                    task.priority === TaskPriority.HIGH ? 'bg-red-100 text-red-600' : 
                    task.priority === TaskPriority.MEDIUM ? 'bg-orange-100 text-orange-600' : 
                    'bg-blue-100 text-blue-600'
                  }`}>
                    {task.priority}
                  </span>
                  <div className="flex items-center gap-1 text-slate-400 text-xs">
                    <Clock size={12} />
                    <span>{task.estimatedMinutes}m</span>
                  </div>
                </div>
              </div>

              <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                <button 
                  onClick={() => onDeleteTask(task.id)}
                  className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-all"
                >
                  <Trash2 size={18} />
                </button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default TodoList;

import React from 'react';
import { Task, EisenhowerQuadrant, ThemeType } from '../../types';
import { THEMES } from '../../constants';
import { Zap, Calendar, Users, Trash } from 'lucide-react';

interface EisenhowerMatrixProps {
  tasks: Task[];
  onUpdateTask: (id: string, updates: Partial<Task>) => void;
  theme: ThemeType;
}

const EisenhowerMatrix: React.FC<EisenhowerMatrixProps> = ({ tasks, onUpdateTask, theme }) => {
  const currentTheme = THEMES[theme];

  const getTasksByQuadrant = (quadrant: EisenhowerQuadrant) => {
    return tasks.filter(t => t.quadrant === quadrant);
  };

  const Quadrant = ({ 
    type, 
    title, 
    icon: Icon, 
    colorClass, 
    description 
  }: { 
    type: EisenhowerQuadrant; 
    title: string; 
    icon: any; 
    colorClass: string;
    description: string;
  }) => {
    const quadrantTasks = getTasksByQuadrant(type);

    return (
      <div className={`${currentTheme.card} border ${currentTheme.accent} rounded-3xl p-5 flex flex-col h-full shadow-sm overflow-hidden`}>
        <div className="flex items-start justify-between mb-4">
          <div className="flex items-center gap-2">
            <div className={`p-2 rounded-lg ${colorClass} bg-opacity-10 text-opacity-100`}>
              <Icon size={20} className={colorClass.replace('bg-', 'text-')} />
            </div>
            <div>
              <h3 className="font-bold text-sm leading-none mb-1">{title}</h3>
              <p className="text-[10px] text-slate-400 uppercase tracking-tighter">{description}</p>
            </div>
          </div>
          <span className="bg-slate-100 dark:bg-slate-800 px-2 py-0.5 rounded text-[10px] font-bold">{quadrantTasks.length}</span>
        </div>

        <div className="flex-1 space-y-2 overflow-y-auto pr-2 custom-scrollbar">
          {quadrantTasks.length === 0 ? (
            <div className="h-full flex items-center justify-center border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-2xl p-4">
              <p className="text-[10px] text-slate-300 text-center italic">Dépose ou crée une tâche ici pour prioriser.</p>
            </div>
          ) : (
            quadrantTasks.map(t => (
              <div 
                key={t.id} 
                className="p-3 bg-slate-50 dark:bg-slate-800/50 rounded-xl border border-slate-100 dark:border-slate-800 group"
              >
                <div className="text-xs font-semibold truncate">{t.title}</div>
              </div>
            ))
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6 animate-in fade-in zoom-in-95 duration-500">
      <div className="bg-blue-50 dark:bg-blue-900/20 p-4 rounded-2xl border border-blue-100 dark:border-blue-900/30">
        <p className="text-xs text-blue-700 dark:text-blue-300">
          <strong>Comment ça marche ?</strong> Classe tes tâches selon leur importance et urgence pour ne plus jamais procrastiner sur l'essentiel.
        </p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 h-[calc(100vh-320px)] min-h-[500px]">
        <Quadrant 
          type={EisenhowerQuadrant.DO_FIRST} 
          title="Faire immédiatement" 
          icon={Zap} 
          colorClass="bg-red-500"
          description="Urgent & Important"
        />
        <Quadrant 
          type={EisenhowerQuadrant.SCHEDULE} 
          title="Planifier" 
          icon={Calendar} 
          colorClass="bg-blue-500"
          description="Important / Non-urgent"
        />
        <Quadrant 
