import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  CheckSquare, 
  Grid2X2, 
  Timer, 
  BarChart3, 
  CalendarDays,
  Search,
  Plus
} from 'lucide-react';
import { Task, TaskStatus, TaskPriority, EisenhowerQuadrant, ThemeType, TaskDifficulty } from './types';
import { THEMES } from './constants';
import Dashboard from './components/Dashboard';
import TodoList from './components/Tasks/TodoList';
import EisenhowerMatrix from './components/Matrix/EisenhowerMatrix';
import Pomodoro from './components/Focus/Pomodoro';
import ProgressTracking from './components/Stats/ProgressTracking';
import SmartPlanning from './components/Planning/SmartPlanning';
import TaskModal from './components/Tasks/TaskModal';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [tasks, setTasks] = useState<Task[]>([]);
  const [theme, setTheme] = useState<ThemeType>('lime');
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | undefined>(undefined);

  useEffect(() => {
    const savedTasks = localStorage.getItem('evo_tasks');
    const savedTheme = localStorage.getItem('evo_theme');
    if (savedTasks) setTasks(JSON.parse(savedTasks));
    if (savedTheme) setTheme(savedTheme as ThemeType);
  }, []);

  useEffect(() => {
    localStorage.setItem('evo_tasks', JSON.stringify(tasks));
    localStorage.setItem('evo_theme', theme);
    if (theme === 'dark') {
      document.body.classList.add('dark');
      document.body.style.backgroundColor = '#020617';
    } else {
      document.body.classList.remove('dark');
      document.body.style.backgroundColor = '#f8fafc';
    }
  }, [tasks, theme]);

  const addTask = (taskData: any) => {
    const newTask: Task = {
      ...taskData,
      id: Math.random().toString(36).substr(2, 9),
      createdAt: Date.now(),
      actualMinutes: 0
    };
    setTasks([...tasks, newTask]);
    setIsTaskModalOpen(false);
  };

  const updateTask = (id: string, updates: Partial<Task>) => {
    setTasks(tasks.map(t => t.id === id ? { ...t, ...updates } : t));
    setIsTaskModalOpen(false);
    setEditingTask(undefined);
  };

  const deleteTask = (id: string) => {
    setTasks(tasks.filter(t => t.id !== id));
  };

  const openEditModal = (task: Task) => {
    setEditingTask(task);
    setIsTaskModalOpen(true);
  };

  const currentTheme = THEMES[theme];

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard tasks={tasks} theme={theme} onAddTask={() => setIsTaskModalOpen(true)} onUpdateTask={updateTask} />;
      case 'tasks':
        return <TodoList tasks={tasks} onUpdateTask={updateTask} onDeleteTask={deleteTask} onEditTask={openEditModal} onAddTask={() => setIsTaskModalOpen(true)} theme={theme} />;
      case 'matrix':
        return <EisenhowerMatrix tasks={tasks} onUpdateTask={updateTask} theme={theme} />;
      case 'planning':
        return <SmartPlanning tasks={tasks} theme={theme} />;
      case 'focus':
        return <Pomodoro theme={theme} tasks={tasks} onUpdateTask={updateTask} />;
      case 'stats':
        return <ProgressTracking tasks={tasks} theme={theme} />;
      default:
        return <Dashboard tasks={tasks} theme={theme} onAddTask={() => setIsTaskModalOpen(true)} onUpdateTask={updateTask} />;
    }
  };

  const navItems = [
    { id: 'dashboard', label: 'Accueil', icon: LayoutDashboard },
    { id: 'tasks', label: 'Tâches', icon: CheckSquare },
    { id: 'matrix', label: 'Priorités', icon: Grid2X2 },
    { id: 'planning', label: 'Planning IA', icon: CalendarDays },
    { id: 'focus', label: 'Focus', icon: Timer },
    { id: 'stats', label: 'Analyses', icon: BarChart3 },
  ];

  return (
    <div className={`min-h-screen flex flex-col md:flex-row ${currentTheme.bg} ${currentTheme.text} transition-colors duration-300`}>
      <aside className={`hidden md:flex flex-col w-64 ${currentTheme.card} border-r ${currentTheme.accent} h-screen sticky top-0`}>
        <div className="p-6 flex items-center gap-3">
          <div className={`w-10 h-10 rounded-xl ${currentTheme.primary} flex items-center justify-center text-white shadow-lg`}>
            <BarChart3 size={24} />
          </div>
          <span className="text-2xl font-bold tracking-tight">Evo</span>
        </div>
        <nav className="flex-1 px-4 space-y-2 mt-4">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-200 ${
                activeTab === item.id 
                ? `${currentTheme.primary} text-white shadow-md` 
                : `hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-500 dark:text-slate-400`
              }`}
            >
              <item.icon size={20} />
              <span className="font-medium">{item.label}</span>
            </button>
          ))}
        </nav>
        <div className="p-4 border-t border-slate-100 dark:border-slate-800">
          <div className="flex justify-between items-center mb-4 px-2">
            <span className="text-sm font-semibold text-slate-400">THÈME</span>
            <div className="flex gap-1">
              {(Object.keys(THEMES) as ThemeType[]).map((t) => (
                <button
                  key={t}
                  onClick={() => setTheme(t)}
                  className={`w-6 h-6 rounded-full border-2 ${theme === t ? 'border-slate-400' : 'border-transparent'} ${THEMES[t].primary}`}
                />
              ))}
            </div>
          </div>
        </div>
      </aside>

      <nav className={`md:hidden fixed bottom-0 left-0 right-0 z-50 ${currentTheme.card} border-t ${currentTheme.accent} px-2 py-3 flex justify-around shadow-2xl`}>
        {navItems.map((item) => (
          <button key={item.id} onClick={() => setActiveTab(item.id)} className={`flex flex-col items-center gap-1 p-2 ${activeTab === item.id ? currentTheme.secondary : 'text-slate-400'}`}>
            <item.icon size={20} />
            <span className="text-[10px] font-medium">{item.label}</span>
          </button>
        ))}
      </nav>

      <main className="flex-1 p-4 md:p-8 pb-24 md:pb-8 max-w-7xl mx-auto w-full">
        <header className="flex justify-between items-center mb-8">
          <div>
            <h1 className="text-2xl font-bold">Bonjour ! 👋</h1>
            <p className="text-slate-500 text-sm">Prêt pour une session de travail efficace ?</p>
          </div>
          <button 
            onClick={() => setIsTaskModalOpen(true)}
            className={`${currentTheme.primary} text-white p-3 rounded-2xl shadow-lg flex items-center gap-2 hover:scale-105 transition-transform`}
          >
            <Plus size={20} /> <span className="hidden sm:inline">Nouvelle Tâche</span>
          </button>
        </header>

        {renderContent()}

        {isTaskModalOpen && (
          <TaskModal 
            theme={theme}
            task={editingTask}
            onClose={() => { setIsTaskModalOpen(false); setEditingTask(undefined); }}
            onSubmit={editingTask ? (data) => updateTask(editingTask.id, data) : addTask}
          />
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Task, TaskPriority, TaskDifficulty, EisenhowerQuadrant, TaskStatus, ThemeType } from '../../types';
import { THEMES } from '../../constants';
import { X, Check } from 'lucide-react';

interface TaskModalProps {
  theme: ThemeType;
  task?: Task;
  onClose: () => void;
  onSubmit: (taskData: any) => void;
}

const TaskModal: React.FC<TaskModalProps> = ({ theme, task, onClose, onSubmit }) => {
  const currentTheme = THEMES[theme];
  const [title, setTitle] = useState(task?.title || '');
  const [priority, setPriority] = useState<TaskPriority>(task?.priority || TaskPriority.MEDIUM);
  const [difficulty, setDifficulty] = useState<TaskDifficulty>(task?.difficulty || TaskDifficulty.MEDIUM);
  const [quadrant, setQuadrant] = useState<EisenhowerQuadrant>(task?.quadrant || EisenhowerQuadrant.DO_FIRST);
  const [estimatedMinutes, setEstimatedMinutes] = useState(task?.estimatedMinutes || 30);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) return;
    onSubmit({
      title,
      priority,
      difficulty,
      quadrant,
      estimatedMinutes,
      status: task?.status || TaskStatus.TODO,
    });
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
      <div className={`${currentTheme.card} w-full max-w-md rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300`}>
        <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center">
          <h2 className="text-xl font-bold">{task ? 'Modifier la tâche' : 'Nouvelle tâche'}</h2>
          <button onClick={onClose} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition-colors">
            <X size={20} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-6">
          <div className="space-y-2">
            <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">Titre de la tâche</label>
            <input 
              autoFocus
              type="text" 
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="Ex: Réviser le chapitre 3 d'Histoire"
              className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-2xl px-4 py-4 text-sm focus:ring-2 ring-blue-500 transition-all outline-none"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">Difficulté</label>
              <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-xl">
                {Object.values(TaskDifficulty).map((d) => (
                  <button
                    key={d}
                    type="button"
                    onClick={() => setDifficulty(d)}
                    className={`flex-1 py-2 text-[10px] font-bold rounded-lg transition-all ${difficulty === d ? 'bg-white dark:bg-slate-700 shadow-sm' : 'text-slate-400'}`}
                  >
                    {d === 'easy' ? 'Facile' : d === 'medium' ? 'Moyen' : 'Dur'}
                  </button>
                ))}
              </div>
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">Temps (min)</label>
              <input 
                type="number" 
                value={estimatedMinutes}
                onChange={(e) => setEstimatedMinutes(parseInt(e.target.value))}
                className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-xl px-4 py-2 text-sm focus:ring-2 ring-blue-500 transition-all outline-none"
              />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">Type (Eisenhower)</label>
            <select 
              value={quadrant}
              onChange={(e) => setQuadrant(e.target.value as EisenhowerQuadrant)}
              className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-2xl px-4 py-3 text-sm focus:ring-2 ring-blue-500 outline-none"
            >
              <option value={EisenhowerQuadrant.DO_FIRST}>🔴 Urgent & Important</option>
              <option value={EisenhowerQuadrant.SCHEDULE}>🔵 Important (Non-urgent)</option>
              <option value={EisenhowerQuadrant.DELEGATE}>🟡 Urgent (Non-important)</option>
              <option value={EisenhowerQuadrant.ELIMINATE}>⚪ Ni l'un ni l'autre</option>
            </select>
          </div>

          <button 
            type="submit" 
            className={`w-full ${currentTheme.primary} text-white font-bold py-4 rounded-2xl shadow-xl flex items-center justify-center gap-2 hover:opacity-90 transition-all`}
          >
            <Check size={20} /> {task ? 'Enregistrer' : 'Créer la tâche'}
          </button>
        </form>
      </div>
    </div>
  );
};

