import React, { useState } from 'react';
import { Task, ThemeType, TaskStatus } from '../../types';
import { THEMES } from '../../constants';
import { GoogleGenAI } from '@google/genai';
import { Sparkles, CalendarDays, BrainCircuit, Loader2, Info } from 'lucide-react';

interface SmartPlanningProps {
  tasks: Task[];
  theme: ThemeType;
}

const SmartPlanning: React.FC<SmartPlanningProps> = ({ tasks, theme }) => {
  const currentTheme = THEMES[theme];
  const [planning, setPlanning] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [justification, setJustification] = useState('');

  const generatePlanning = async () => {
    setIsLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const activeTasks = tasks.filter(t => t.status !== TaskStatus.DONE);

      const prompt = `Agis comme un expert en productivité EdTech. Voici ma liste de tâches d'étudiant :
      ${JSON.stringify(activeTasks.map(t => ({ 
        titre: t.title, 
        priorite: t.priority, 
        difficulte: t.difficulty, 
        quadrant: t.quadrant, 
        duree_estimee: t.estimatedMinutes 
      })))}

      Génère un planning hebdomadaire optimisé au format JSON. 
      Règles : 
      1. Alterne les tâches difficiles avec les tâches faciles pour éviter la fatigue mentale.
      2. Priorise les tâches 'DO_FIRST' (urgent & important).
      3. Propose des créneaux horaires réalistes (ex: "Lundi Matin", "Mercredi Après-midi").
      4. Inclus une courte justification globale de ta stratégie.

      Format attendu :
      {
        "justification": "...",
        "days": [
          { "day": "Lundi", "slots": [{ "time": "09:00", "task": "...", "reason": "..." }] }
        ]
      }`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { responseMimeType: "application/json" }
      });

      const result = JSON.parse(response.text || '{}');
      setPlanning(result.days || []);
      setJustification(result.justification || '');
    } catch (error) {
      console.error("AI Error:", error);
      alert("Erreur lors de la génération du planning. Vérifie ta connexion.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-10">
      <div className={`${currentTheme.card} p-8 rounded-[2rem] border ${currentTheme.accent} shadow-xl relative overflow-hidden`}>
        <div className="absolute top-0 right-0 p-10 opacity-5 pointer-events-none">
          <BrainCircuit size={160} className={currentTheme.secondary} />
        </div>

        <div className="relative z-10">
          <h2 className="text-3xl font-black mb-4 flex items-center gap-3">
            <Sparkles className="text-amber-400" /> Planning Intelligent IA
          </h2>
          <p className="text-slate-500 max-w-2xl mb-8">
            Notre IA analyse ta charge de travail, la difficulté de tes tâches et tes priorités pour te proposer l'ordre de passage idéal cette semaine.
          </p>

          <button 
            onClick={generatePlanning}
            disabled={isLoading || tasks.filter(t => t.status !== TaskStatus.DONE).length === 0}
            className={`${currentTheme.primary} text-white px-8 py-4 rounded-2xl font-bold flex items-center gap-3 shadow-lg hover:opacity-90 transition-all disabled:opacity-50 disabled:cursor-not-allowed active:scale-95`}
          >
            {isLoading ? <Loader2 className="animate-spin" /> : <Sparkles />}
            {isLoading ? 'Analyse en cours...' : 'Générer mon planning de la semaine'}
          </button>
        </div>
      </div>

      {justification && (
        <div className="bg-amber-50 dark:bg-amber-900/20 p-4 rounded-2xl border border-amber-100 dark:border-amber-900/30 flex items-start gap-3">
          <Info className="text-amber-500 mt-1 flex-shrink-0" />
          <p className="text-sm text-amber-800 dark:text-amber-200 italic">{justification}</p>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {planning.length > 0 ? (
          planning.map((dayData, idx) => (
            <div key={idx} className={`${currentTheme.card} p-6 rounded-3xl border ${currentTheme.accent} shadow-sm animate-in slide-in-from-bottom-4 duration-500`} style={{ animationDelay: `${idx * 100}ms` }}>
              <h3 className="text-xl font-black mb-4 border-b pb-2 flex items-center gap-2">
                <CalendarDays size={20} className={currentTheme.secondary} />
                {dayData.day}
              </h3>
              <div className="space-y-4">
                {dayData.slots.map((slot: any, sIdx: number) => (
                  <div key={sIdx} className="relative pl-4 border-l-2 border-slate-100 dark:border-slate-800 py-1">
                    <div className="absolute left-[-5px] top-2 w-2 h-2 rounded-full bg-slate-300" />
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{slot.time}</span>
                    <p className="font-bold text-sm leading-tight">{slot.task}</p>
                    <p className="text-[10px] text-slate-400 mt-1 italic">{slot.reason}</p>
                  </div>
                ))}
              </div>
            </div>
          ))
        ) : !isLoading && (
          <div className="col-span-full py-20 text-center text-slate-400">
            {tasks.filter(t => t.status !== TaskStatus.DONE).length === 0 
              ? "Ajoute des tâches pour que l'IA puisse organiser ta semaine ! 📝"
              : "Appuie sur le bouton ci-dessus pour laisser l'IA organiser tes révisions."}
          </div>
        )}
      </div>
    </div>
  );
};

export default SmartPlanning;

import React, { useState } from 'react';
import { Task, TaskStatus, ThemeType, TaskDifficulty } from '../../types';
import { THEMES } from '../../constants';
import { Trash2, CheckCircle2, Circle, Clock, Edit2, AlertCircle } from 'lucide-react';

interface TodoListProps {
  tasks: Task[];
  onUpdateTask: (id: string, updates: Partial<Task>) => void;
  onDeleteTask: (id: string) => void;
  onEditTask: (task: Task) => void;
  onAddTask: () => void;
  theme: ThemeType;
}

const TodoList: React.FC<TodoListProps> = ({ tasks, onUpdateTask, onDeleteTask, onEditTask, onAddTask, theme }) => {
  const [filter, setFilter] = useState<TaskStatus | 'all'>('all');
  const currentTheme = THEMES[theme];

  const filteredTasks = tasks.filter(t => filter === 'all' || t.status === filter);

  const toggleStatus = (task: Task) => {
    const nextStatus = task.status === TaskStatus.DONE ? TaskStatus.TODO : TaskStatus.DONE;
    onUpdateTask(task.id, { status: nextStatus });
  };

  const getDifficultyColor = (diff: TaskDifficulty) => {
    switch(diff) {
      case 'easy': return 'text-emerald-500';
      case 'medium': return 'text-amber-500';
      case 'hard': return 'text-rose-500';
      default: return 'text-slate-500';
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div className="flex gap-2">
          {(['all', TaskStatus.TODO, TaskStatus.DONE] as const).map(f => (
            <button
              key={f}
              onClick={() => setFilter(f)}
              className={`px-4 py-2 rounded-full text-sm font-medium transition-all ${
                filter === f 
                ? `${currentTheme.primary} text-white` 
                : 'bg-white dark:bg-slate-800 text-slate-500 border border-slate-200 dark:border-slate-800'
              }`}
            >
              {f === 'all' ? 'Tous' : f === TaskStatus.TODO ? 'À faire' : 'Terminé'}
            </button>
          ))}
        </div>
      </div>

      <div className="space-y-3">
        {filteredTasks.length === 0 ? (
          <div className="text-center py-20 bg-white/50 dark:bg-slate-900/50 rounded-3xl border border-dashed border-slate-300 dark:border-slate-800">
            <p className="text-slate-400">Aucune tâche trouvée. ✨</p>
          </div>
        ) : (
          filteredTasks.map(task => (
            <div 
              key={task.id} 
              className={`group ${currentTheme.card} border ${currentTheme.accent} p-4 rounded-2xl flex items-center gap-4 shadow-sm hover:shadow-md transition-all animate-in slide-in-from-left-2`}
            >
              <button 
                onClick={() => toggleStatus(task)}
                className={`transition-colors ${task.status === TaskStatus.DONE ? 'text-green-500' : 'text-slate-300 hover:text-slate-400'}`}
              >
                {task.status === TaskStatus.DONE ? <CheckCircle2 size={24} /> : <Circle size={24} />}
              </button>

              <div className="flex-1">
                <div className="flex items-center gap-2">
                  <h4 className={`font-semibold ${task.status === TaskStatus.DONE ? 'line-through text-slate-400' : ''}`}>
                    {task.title}
                  </h4>
                  <span className={`text-[10px] font-bold ${getDifficultyColor(task.difficulty)}`}>
                    • {task.difficulty === 'easy' ? 'Facile' : task.difficulty === 'medium' ? 'Moyen' : 'Dur'}
                  </span>
                </div>
                <div className="flex items-center gap-3 mt-1">
                  <span className={`text-[9px] uppercase font-black px-2 py-0.5 rounded ${
                    task.quadrant === 'do_first' ? 'bg-red-100 text-red-600' : 
                    task.quadrant === 'schedule' ? 'bg-blue-100 text-blue-600' : 
                    'bg-slate-100 text-slate-600'
                  }`}>
                    {task.quadrant.replace('_', ' ')}
                  </span>
                  <div className="flex items-center gap-1 text-slate-400 text-xs">
                    <Clock size={12} />
                    <span>{task.estimatedMinutes}m</span>
                  </div>
                </div>
              </div>

              <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                <button 
                  onClick={() => onEditTask(task)}
                  className="p-2 text-slate-400 hover:text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg transition-all"
                >
                  <Edit2 size={18} />
                </button>
                <button 
                  onClick={() => onDeleteTask(task.id)}
                  className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-all"
                >
                  <Trash2 size={18} />
                </button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default TodoList;

