import React, { useMemo } from 'react';
import { Task, TaskStatus, ThemeType, EisenhowerQuadrant } from '../../types';
import { THEMES } from '../../constants';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface ProgressTrackingProps {
  tasks: Task[];
  theme: ThemeType;
}

const ProgressTracking: React.FC<ProgressTrackingProps> = ({ tasks, theme }) => {
  const currentTheme = THEMES[theme];

  // 1. Calculer les données des 7 derniers jours pour le graphique
  const weeklyData = useMemo(() => {
    const days = ['Dim', 'Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam'];
    const result = [];
    const now = new Date();

    for (let i = 6; i >= 0; i--) {
      const d = new Date();
      d.setDate(now.getDate() - i);
      const dayName = days[d.getDay()];
      const dayStart = new Date(d.setHours(0, 0, 0, 0)).getTime();
      const dayEnd = new Date(d.setHours(23, 59, 59, 999)).getTime();

      const completedOnDay = tasks.filter(t => 
        t.status === TaskStatus.DONE && 
        t.completedAt && 
        t.completedAt >= dayStart && 
        t.completedAt <= dayEnd
      ).length;

      result.push({ name: dayName, completed: completedOnDay, goal: 3 }); // Objectif arbitraire de 3 tâches/jour
    }
    return result;
  }, [tasks]);

  // 2. Calculer le Streak (Jours consécutifs avec au moins 1 tâche terminée)
  const streak = useMemo(() => {
    let currentStreak = 0;
    const now = new Date();
    const sortedCompletedDates = tasks
      .filter(t => t.status === TaskStatus.DONE && t.completedAt)
      .map(t => new Date(t.completedAt!).setHours(0,0,0,0))
      .sort((a, b) => b - a);

    const uniqueDates = Array.from(new Set(sortedCompletedDates));

    let checkDate = new Date();
    checkDate.setHours(0,0,0,0);

    // Si pas de tâche aujourd'hui, on vérifie si on a fini hier pour continuer le streak
    const hasTaskToday = uniqueDates.includes(checkDate.getTime());
    if (!hasTaskToday) {
      checkDate.setDate(checkDate.getDate() - 1);
    }

    for (const date of uniqueDates) {
      if (date === checkDate.getTime()) {
        currentStreak++;
        checkDate.setDate(checkDate.getDate() - 1);
      } else {
        break;
      }
    }
    return currentStreak;
  }, [tasks]);

  // 3. Calculer les scores académiques réels
  const metrics = useMemo(() => {
    const completedTasks = tasks.filter(t => t.status === TaskStatus.DONE);

    // Organisation : Ratio de tâches avec quadrant assigné
    const orgScore = tasks.length > 0 
      ? Math.round((tasks.filter(t => t.quadrant !== EisenhowerQuadrant.ELIMINATE).length / tasks.length) * 100) 
      : 0;

    // Discipline : Respect des temps estimés (Actual vs Estimated)
    const disciplineScore = completedTasks.length > 0
      ? Math.round(Math.min(100, (completedTasks.reduce((acc, t) => acc + (t.estimatedMinutes / Math.max(1, t.actualMinutes || t.estimatedMinutes)), 0) / completedTasks.length) * 100))
      : 0;

    // Priorisation : Ratio de tâches DO_FIRST terminées par rapport au total DO_FIRST
    const doFirstTasks = tasks.filter(t => t.quadrant === EisenhowerQuadrant.DO_FIRST);
    const priorisationScore = doFirstTasks.length > 0
      ? Math.round((doFirstTasks.filter(t => t.status === TaskStatus.DONE).length / doFirstTasks.length) * 100)
      : 0;

    // Assiduité : Taux de complétion global
    const assiduiteScore = tasks.length > 0 
      ? Math.round((completedTasks.length / tasks.length) * 100)
      : 0;

    return {
      organisation: orgScore,
      discipline: disciplineScore,
      priorisation: priorisationScore,
      assiduite: assiduiteScore
    };
  }, [tasks]);

  const totalFocusTime = tasks.reduce((acc, t) => acc + (t.actualMinutes || 0), 0);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-10">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className={`${currentTheme.card} rounded-3xl p-8 border ${currentTheme.accent} shadow-sm`}>
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-xl font-bold">Activité Hebdomadaire</h3>
            <span className="text-[10px] font-bold bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded text-slate-400">7 DERNIERS JOURS</span>
          </div>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={weeklyData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 12, fill: '#94a3b8' }} />
                <YAxis hide />
                <Tooltip 
                  cursor={{ fill: 'transparent' }}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                />
                <Bar dataKey="completed" radius={[6, 6, 0, 0]}>
                  {weeklyData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.completed >= entry.goal ? (theme === 'lime' ? '#84cc16' : '#3b82f6') : '#cbd5e1'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
          <p className="text-sm text-slate-400 mt-4 text-center">Tâches complétées par rapport à l'objectif quotidien</p>
        </div>

        <div className="flex flex-col gap-6">
          <div className={`${currentTheme.card} rounded-3xl p-6 border ${currentTheme.accent} shadow-sm flex-1 flex flex-col justify-center items-center text-center relative overflow-hidden group`}>
            <div className={`absolute inset-0 ${currentTheme.primary} opacity-0 group-hover:opacity-5 transition-opacity pointer-events-none`} />
            <span className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-2">Temps Focus Total</span>
            <h4 className="text-5xl font-black mb-1 tabular-nums">{Math.floor(totalFocusTime / 60)}h {totalFocusTime % 60}m</h4>
            <p className="text-sm text-slate-500">investis dans ta réussite</p>
          </div>

          <div className={`${currentTheme.card} rounded-3xl p-6 border ${currentTheme.accent} shadow-sm flex-1 flex flex-col justify-center items-center text-center relative overflow-hidden group`}>
             <div className="absolute -right-4 -top-4 text-6xl opacity-10 grayscale group-hover:grayscale-0 transition-all duration-500">🔥</div>
            <span className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-2">Série Actuelle</span>
            <h4 className="text-5xl font-black mb-1 tabular-nums">{streak} Jours</h4>
            <p className="text-sm text-slate-500">
              {streak === 0 ? "Commence ta série aujourd'hui !" : "La régularité est la clé du succès."}
            </p>
          </div>
        </div>
      </div>

      <div className={`${currentTheme.card} rounded-3xl p-8 border ${currentTheme.accent} shadow-sm`}>
         <div className="flex justify-between items-center mb-6">
            <h3 className="text-xl font-bold">Profil d'Étudiant</h3>
            <p className="text-xs text-slate-400">Basé sur ton activité récente</p>
         </div>
         <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
            <div className="space-y-6">
              <ProgressBar label="Organisation" progress={metrics.organisation} color="bg-blue-500" description="Capacité à classer les tâches par importance." />
              <ProgressBar label="Discipline (Focus)" progress={metrics.discipline} color="bg-purple-500" description="Respect des temps de travail prévus." />
            </div>
            <div className="space-y-6">
              <ProgressBar label="Priorisation" progress={metrics.priorisation} color="bg-lime-500" description="Efficacité sur les tâches critiques." />
              <ProgressBar label="Assiduité" progress={metrics.assiduite} color="bg-orange-500" description="Taux global de complétion des objectifs." />
            </div>
         </div>
      </div>
    </div>
  );
};

const ProgressBar = ({ label, progress, color, description }: { label: string; progress: number; color: string; description: string }) => (
  <div className="space-y-2">
    <div className="flex justify-between text-xs font-bold px-1">
      <span className="text-slate-700 dark:text-slate-300 uppercase tracking-tight">{label}</span>
      <span className="tabular-nums font-black">{progress}%</span>
    </div>
    <div className="h-4 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden shadow-inner">
      <div 
        className={`h-full ${color} rounded-full transition-all duration-1000 ease-out shadow-lg`} 
        style={{ width: `${progress}%` }} 
      />
    </div>
    <p className="text-[10px] text-slate-400 italic px-1">{description}</p>
  </div>
);

export default ProgressTracking;

export enum TaskStatus {
  TODO = 'todo',
  IN_PROGRESS = 'in_progress',
  DONE = 'done'
}

export enum TaskPriority {
  LOW = 'low',
  MEDIUM = 'medium',
  HIGH = 'high'
}

export enum TaskDifficulty {
  EASY = 'easy',
  MEDIUM = 'medium',
  HARD = 'hard'
}

export enum EisenhowerQuadrant {
  DO_FIRST = 'do_first',      // Urgent & Important
  SCHEDULE = 'schedule',      // Not Urgent & Important
  DELEGATE = 'delegate',      // Urgent & Not Important
  ELIMINATE = 'eliminate'     // Not Urgent & Not Important
}

export interface Unavailability {
  id: string;
  day: string; // 'Lundi', 'Mardi', etc.
  startTime: string;
  endTime: string;
  reason: string;
}

export interface Task {
  id: string;
  title: string;
  description?: string;
  status: TaskStatus;
  priority: TaskPriority;
  difficulty: TaskDifficulty;
  quadrant: EisenhowerQuadrant;
  dueDate?: string;
  estimatedMinutes: number;
  actualMinutes: number;
  createdAt: number;
  completedAt?: number;
}

export type ThemeType = 'lime' | 'blue' | 'purple' | 'dark';

export interface AppState {
  tasks: Task[];
  theme: ThemeType;
  unavailabilities: Unavailability[];
  pomodoroConfig: {
    workTime: number;
    shortBreak: number;
    longBreak: number;
  };
}

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  CheckSquare, 
  Grid2X2, 
  Timer, 
  BarChart3, 
  CalendarDays,
  Plus
} from 'lucide-react';
import { Task, TaskStatus, ThemeType, Unavailability } from './types';
import { THEMES } from './constants';
import Dashboard from './components/Dashboard';
import TodoList from './components/Tasks/TodoList';
import EisenhowerMatrix from './components/Matrix/EisenhowerMatrix';
import Pomodoro from './components/Focus/Pomodoro';
import ProgressTracking from './components/Stats/ProgressTracking';
import SmartPlanning from './components/Planning/SmartPlanning';
import TaskModal from './components/Tasks/TaskModal';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [tasks, setTasks] = useState<Task[]>([]);
  const [unavailabilities, setUnavailabilities] = useState<Unavailability[]>([]);
  const [theme, setTheme] = useState<ThemeType>('lime');
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | undefined>(undefined);

  useEffect(() => {
    const savedTasks = localStorage.getItem('evo_tasks');
    const savedTheme = localStorage.getItem('evo_theme');
    const savedUnavail = localStorage.getItem('evo_unavailabilities');
    if (savedTasks) setTasks(JSON.parse(savedTasks));
    if (savedTheme) setTheme(savedTheme as ThemeType);
    if (savedUnavail) setUnavailabilities(JSON.parse(savedUnavail));
  }, []);

  useEffect(() => {
    localStorage.setItem('evo_tasks', JSON.stringify(tasks));
    localStorage.setItem('evo_theme', theme);
    localStorage.setItem('evo_unavailabilities', JSON.stringify(unavailabilities));

    if (theme === 'dark') {
      document.body.classList.add('dark');
      document.body.style.backgroundColor = '#020617';
    } else {
      document.body.classList.remove('dark');
      document.body.style.backgroundColor = '#f8fafc';
    }
  }, [tasks, theme, unavailabilities]);

  const addTask = (taskData: any) => {
    const newTask: Task = {
      ...taskData,
      id: Math.random().toString(36).substr(2, 9),
      createdAt: Date.now(),
      actualMinutes: 0
    };
    setTasks([...tasks, newTask]);
    setIsTaskModalOpen(false);
  };

  const updateTask = (id: string, updates: Partial<Task>) => {
    setTasks(tasks.map(t => {
      if (t.id === id) {
        const isNowDone = updates.status === TaskStatus.DONE && t.status !== TaskStatus.DONE;
        return { 
          ...t, 
          ...updates, 
          completedAt: isNowDone ? Date.now() : (updates.status === TaskStatus.TODO ? undefined : t.completedAt)
        };
      }
      return t;
    }));
    setIsTaskModalOpen(false);
    setEditingTask(undefined);
  };

  const addUnavailability = (unavail: Omit<Unavailability, 'id'>) => {
    setUnavailabilities([...unavailabilities, { ...unavail, id: Math.random().toString(36).substr(2, 9) }]);
  };

  const deleteUnavailability = (id: string) => {
    setUnavailabilities(unavailabilities.filter(u => u.id !== id));
  };

  const currentTheme = THEMES[theme];

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <Dashboard 
            tasks={tasks} 
            theme={theme} 
            unavailabilities={unavailabilities}
            onAddTask={() => setIsTaskModalOpen(true)} 
            onUpdateTask={updateTask}
            onAddUnavailability={addUnavailability}
            onDeleteUnavailability={deleteUnavailability}
          />
        );
      case 'tasks':
        return <TodoList tasks={tasks} onUpdateTask={updateTask} onDeleteTask={(id) => setTasks(tasks.filter(t => t.id !== id))} onEditTask={(t) => { setEditingTask(t); setIsTaskModalOpen(true); }} onAddTask={() => setIsTaskModalOpen(true)} theme={theme} />;
      case 'matrix':
        return <EisenhowerMatrix tasks={tasks} onUpdateTask={updateTask} theme={theme} />;
      case 'planning':
        return <SmartPlanning tasks={tasks} unavailabilities={unavailabilities} theme={theme} />;
      case 'focus':
        return <Pomodoro theme={theme} tasks={tasks} onUpdateTask={updateTask} />;
      case 'stats':
        return <ProgressTracking tasks={tasks} theme={theme} />;
      default:
        return <Dashboard tasks={tasks} theme={theme} unavailabilities={unavailabilities} onAddTask={() => setIsTaskModalOpen(true)} onUpdateTask={updateTask} onAddUnavailability={addUnavailability} onDeleteUnavailability={deleteUnavailability} />;
    }
  };

  const navItems = [
    { id: 'dashboard', label: 'Accueil', icon: LayoutDashboard },
    { id: 'tasks', label: 'Tâches', icon: CheckSquare },
    { id: 'matrix', label: 'Priorités', icon: Grid2X2 },
    { id: 'planning', label: 'Planning IA', icon: CalendarDays },
    { id: 'focus', label: 'Focus', icon: Timer },
    { id: 'stats', label: 'Analyses', icon: BarChart3 },
  ];

  return (
    <div className={`min-h-screen flex flex-col md:flex-row ${currentTheme.bg} ${currentTheme.text} transition-colors duration-300`}>
      <aside className={`hidden md:flex flex-col w-64 ${currentTheme.card} border-r ${currentTheme.accent} h-screen sticky top-0`}>
        <div className="p-6 flex items-center gap-3">
          <div className={`w-10 h-10 rounded-xl ${currentTheme.primary} flex items-center justify-center text-white shadow-lg`}>
            <BarChart3 size={24} />
          </div>
          <span className="text-2xl font-bold tracking-tight">Evo</span>
        </div>
        <nav className="flex-1 px-4 space-y-2 mt-4">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-200 ${
                activeTab === item.id 
                ? `${currentTheme.primary} text-white shadow-md` 
                : `hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-500 dark:text-slate-400`
              }`}
            >
              <item.icon size={20} />
              <span className="font-medium">{item.label}</span>
            </button>
          ))}
        </nav>
        <div className="p-4 border-t border-slate-100 dark:border-slate-800">
          <div className="flex justify-between items-center mb-4 px-2">
            <span className="text-sm font-semibold text-slate-400">THÈME</span>
            <div className="flex gap-1">
              {(Object.keys(THEMES) as ThemeType[]).map((t) => (
                <button
                  key={t}
                  onClick={() => setTheme(t)}
                  className={`w-6 h-6 rounded-full border-2 ${theme === t ? 'border-slate-400' : 'border-transparent'} ${THEMES[t].primary}`}
                />
              ))}
            </div>
          </div>
        </div>
      </aside>

      <nav className={`md:hidden fixed bottom-0 left-0 right-0 z-50 ${currentTheme.card} border-t ${currentTheme.accent} px-2 py-3 flex justify-around shadow-2xl`}>
        {navItems.map((item) => (
          <button key={item.id} onClick={() => setActiveTab(item.id)} className={`flex flex-col items-center gap-1 p-2 ${activeTab === item.id ? currentTheme.secondary : 'text-slate-400'}`}>
            <item.icon size={20} />
            <span className="text-[10px] font-medium">{item.label}</span>
          </button>
        ))}
      </nav>

      <main className="flex-1 p-4 md:p-8 pb-24 md:pb-8 max-w-7xl mx-auto w-full">
        <header className="flex justify-between items-center mb-8">
          <div>
            <h1 className="text-2xl font-bold">Bonjour ! 👋</h1>
            <p className="text-slate-500 text-sm">Prêt pour une session de travail efficace ?</p>
          </div>
          <button 
            onClick={() => setIsTaskModalOpen(true)}
            className={`${currentTheme.primary} text-white p-3 rounded-2xl shadow-lg flex items-center gap-2 hover:scale-105 transition-transform`}
          >
            <Plus size={20} /> <span className="hidden sm:inline">Nouvelle Tâche</span>
          </button>
        </header>

        {renderContent()}

        {isTaskModalOpen && (
          <TaskModal 
            theme={theme}
            task={editingTask}
            onClose={() => { setIsTaskModalOpen(false); setEditingTask(undefined); }}
            onSubmit={editingTask ? (data) => updateTask(editingTask.id, data) : addTask}
          />
        )}
      </main>
    </div>
  );
};

export default App;

