                    <input type="time" value={newUnavail.endTime} onChange={(e) => setNewUnavail({...newUnavail, endTime: e.target.value})} className="flex-1 bg-white dark:bg-slate-800 border-none rounded-xl px-4 py-2 text-sm outline-none focus:ring-2 ring-blue-500" />
                  </div>
                  <input type="text" placeholder="Raison (Cours, Sport...)" value={newUnavail.reason} onChange={(e) => setNewUnavail({...newUnavail, reason: e.target.value})} className="w-full bg-white dark:bg-slate-800 border-none rounded-xl px-4 py-2 text-sm outline-none focus:ring-2 ring-blue-500" />
                  <button onClick={() => onAddUnavailability(newUnavail)} className={`w-full ${currentTheme.primary} text-white font-bold py-2 rounded-xl text-sm flex items-center justify-center gap-2 shadow-lg hover:opacity-90`}>
                    <Plus size={16} /> Ajouter le blocage
                  </button>
                </div>
              </div>

              {/* List of unavailabilities */}
              <div className="space-y-3 overflow-y-auto max-h-[250px] pr-2 custom-scrollbar">
                {unavailabilities.length === 0 ? (
                  <div className="h-full flex flex-col items-center justify-center border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-2xl p-6 text-center">
                    <p className="text-xs text-slate-400 italic">Aucun créneau bloqué. L'IA suppose que tu es libre 24h/24 !</p>
                  </div>
                ) : (
                  unavailabilities.map(u => (
                    <div key={u.id} className="flex items-center justify-between p-3 bg-white dark:bg-slate-800 rounded-xl border border-slate-100 dark:border-slate-800 group">
                      <div>
                        <p className="text-xs font-bold">{u.day} • {u.reason}</p>
                        <p className="text-[10px] text-slate-400">{u.startTime} - {u.endTime}</p>
                      </div>
                      <button onClick={() => onDeleteUnavailability(u.id)} className="p-1 text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity">
                        <X size={16} />
                      </button>
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>
        </div>

        {/* Quick Add Section */}
        <div className="flex flex-col gap-4">
          <div className={`${currentTheme.card} rounded-3xl p-6 border ${currentTheme.accent} shadow-sm`}>
            <h3 className="font-bold text-lg mb-4 flex items-center gap-2">
              <Plus size={20} className={currentTheme.secondary} /> Ajout Rapide
            </h3>
            <form onSubmit={(e) => {
              e.preventDefault();
              const form = e.target as HTMLFormElement;
              const input = form.elements.namedItem('taskTitle') as HTMLInputElement;
              if (input.value.trim()) {
                onAddTask({ title: input.value, status: TaskStatus.TODO, priority: TaskPriority.MEDIUM, difficulty: 'medium', quadrant: EisenhowerQuadrant.DO_FIRST, estimatedMinutes: 30 });
                form.reset();
              }
            }} className="space-y-4">
              <input name="taskTitle" type="text" placeholder="Quelle est la prochaine étape ?" className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-xl px-4 py-3 text-sm focus:ring-2 ring-lime-500 outline-none" />
              <button className={`w-full ${currentTheme.primary} text-white font-bold py-3 rounded-xl shadow-lg hover:opacity-90`}>Ajouter à ma liste</button>
            </form>
          </div>
          <div className={`${currentTheme.card} rounded-3xl p-6 border ${currentTheme.accent} shadow-sm`}>
            <h3 className="font-bold text-lg mb-2">Conseil de l'IA Evo 🤖</h3>
            <p className="text-sm text-slate-500 leading-relaxed italic">
              "Pense à bloquer tes heures de sommeil et de repas dans ton emploi du temps pour un planning réaliste !"
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

const StatCard: React.FC<{ label: string; value: string; icon: any; color: string; theme: ThemeType }> = ({ label, value, icon: Icon, color, theme }) => {
  const currentTheme = THEMES[theme];
  return (
    <div className={`${currentTheme.card} rounded-2xl p-4 border ${currentTheme.accent} shadow-sm flex items-center gap-4`}>
      <div className={`p-3 rounded-xl bg-slate-50 dark:bg-slate-800 ${color}`}><Icon size={24} /></div>
      <div>
        <p className="text-xs text-slate-400 font-medium">{label}</p>
        <p className="text-lg font-bold">{value}</p>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Task, ThemeType, TaskStatus, Unavailability } from '../../types';
import { THEMES } from '../../constants';
import { GoogleGenAI } from '@google/genai';
import { Sparkles, CalendarDays, BrainCircuit, Loader2, Info, Lock } from 'lucide-react';

interface SmartPlanningProps {
  tasks: Task[];
  unavailabilities: Unavailability[];
  theme: ThemeType;
}

const SmartPlanning: React.FC<SmartPlanningProps> = ({ tasks, unavailabilities, theme }) => {
  const currentTheme = THEMES[theme];
  const [planning, setPlanning] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [justification, setJustification] = useState('');

  const generatePlanning = async () => {
    setIsLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const activeTasks = tasks.filter(t => t.status !== TaskStatus.DONE);

      const prompt = `Agis comme un expert en productivité EdTech. Voici mes données :

      TACHES :
      ${JSON.stringify(activeTasks.map(t => ({ 
        titre: t.title, 
        priorite: t.priority, 
        difficulte: t.difficulty, 
        quadrant: t.quadrant, 
        duree_estimee: t.estimatedMinutes 
      })))}

      INDISPONIBILITÉS (Créneaux où l'utilisateur n'est PAS disponible) :
      ${JSON.stringify(unavailabilities.map(u => ({
        jour: u.day,
        debut: u.startTime,
        fin: u.endTime,
        raison: u.reason
      })))}

      Génère un planning hebdomadaire optimisé au format JSON. 
      Règles CRITIQUES : 
      1. NE PLANIFIE AUCUNE TÂCHE pendant les créneaux d'indisponibilité listés.
      2. Alterne les tâches difficiles avec les tâches faciles.
      3. Priorise les tâches 'DO_FIRST'.
      4. Les créneaux horaires doivent être précis (ex: "14:30 - 15:30") et tenir compte de la durée estimée.

      Format attendu :
      {
        "justification": "Ma stratégie pour cette semaine : ...",
        "days": [
          { "day": "Lundi", "slots": [{ "time": "14:30 - 15:30", "task": "...", "reason": "Placé ici car..." }] }
        ]
      }`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { responseMimeType: "application/json" }
      });

      const result = JSON.parse(response.text || '{}');
      setPlanning(result.days || []);
      setJustification(result.justification || '');
    } catch (error) {
      console.error("AI Error:", error);
      alert("Erreur lors de la génération du planning. Vérifie ta connexion.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-10">
      <div className={`${currentTheme.card} p-8 rounded-[2rem] border ${currentTheme.accent} shadow-xl relative overflow-hidden`}>
        <div className="absolute top-0 right-0 p-10 opacity-5 pointer-events-none">
          <BrainCircuit size={160} className={currentTheme.secondary} />
        </div>

        <div className="relative z-10">
          <h2 className="text-3xl font-black mb-4 flex items-center gap-3">
            <Sparkles className="text-amber-400" /> Planning Sur-Mesure
          </h2>
          <p className="text-slate-500 max-w-2xl mb-8">
            L'IA prend désormais en compte tes <span className="font-bold text-slate-800 dark:text-white">{unavailabilities.length} créneaux bloqués</span> pour te proposer un emploi du temps 100% réaliste.
          </p>

          <button 
            onClick={generatePlanning}
            disabled={isLoading || tasks.filter(t => t.status !== TaskStatus.DONE).length === 0}
            className={`${currentTheme.primary} text-white px-8 py-4 rounded-2xl font-bold flex items-center gap-3 shadow-lg hover:opacity-90 transition-all disabled:opacity-50 active:scale-95`}
          >
            {isLoading ? <Loader2 className="animate-spin" /> : <Sparkles />}
            {isLoading ? 'Calcul du meilleur créneau...' : 'Générer mon planning intelligent'}
          </button>
        </div>
      </div>

      {justification && (
        <div className="bg-amber-50 dark:bg-amber-900/20 p-4 rounded-2xl border border-amber-100 dark:border-amber-900/30 flex items-start gap-3">
          <Info className="text-amber-500 mt-1 flex-shrink-0" />
          <p className="text-sm text-amber-800 dark:text-amber-200 italic">{justification}</p>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {planning.length > 0 ? (
          planning.map((dayData, idx) => (
            <div key={idx} className={`${currentTheme.card} p-6 rounded-3xl border ${currentTheme.accent} shadow-sm animate-in slide-in-from-bottom-4 duration-500`} style={{ animationDelay: `${idx * 100}ms` }}>
              <div className="flex justify-between items-center mb-4 border-b pb-2">
                <h3 className="text-xl font-black flex items-center gap-2">
                  <CalendarDays size={20} className={currentTheme.secondary} />
                  {dayData.day}
                </h3>
                {unavailabilities.some(u => u.day === dayData.day) && <Lock size={14} className="text-slate-300" title="Contraintes détectées" />}
              </div>
              <div className="space-y-4">
                {dayData.slots.map((slot: any, sIdx: number) => (
                  <div key={sIdx} className="relative pl-4 border-l-2 border-slate-100 dark:border-slate-800 py-1">
                    <div className="absolute left-[-5px] top-2 w-2 h-2 rounded-full bg-slate-300" />
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{slot.time}</span>
                    <p className="font-bold text-sm leading-tight">{slot.task}</p>
                    <p className="text-[10px] text-slate-400 mt-1 italic leading-tight">{slot.reason}</p>
                  </div>
                ))}
              </div>
            </div>
          ))
        ) : !isLoading && (
          <div className="col-span-full py-20 text-center text-slate-400">
            {tasks.filter(t => t.status !== TaskStatus.DONE).length === 0 
              ? "Ajoute des tâches pour voir l'IA à l'œuvre ! 📝"
              : "Clique sur le bouton pour que l'IA contourne tes créneaux bloqués."}
          </div>
        )}
      </div>
    </div>
  );
};

export default SmartPlanning;

