import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  CheckSquare, 
  Grid2X2, 
  Timer, 
  BarChart3, 
  CalendarDays,
  Plus
} from 'lucide-react';
import { Task, TaskStatus, ThemeType, Unavailability } from './types';
import { THEMES } from './constants';
import Dashboard from './components/Dashboard';
import TodoList from './components/Tasks/TodoList';
import EisenhowerMatrix from './components/Matrix/EisenhowerMatrix';
import Pomodoro from './components/Focus/Pomodoro';
import ProgressTracking from './components/Stats/ProgressTracking';
import SmartPlanning from './components/Planning/SmartPlanning';
import TaskModal from './components/Tasks/TaskModal';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [tasks, setTasks] = useState<Task[]>([]);
  const [unavailabilities, setUnavailabilities] = useState<Unavailability[]>([]);
  const [theme, setTheme] = useState<ThemeType>('lime');
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | undefined>(undefined);

  useEffect(() => {
    const savedTasks = localStorage.getItem('evo_tasks');
    const savedTheme = localStorage.getItem('evo_theme');
    const savedUnavail = localStorage.getItem('evo_unavailabilities');
    if (savedTasks) setTasks(JSON.parse(savedTasks));
    if (savedTheme) setTheme(savedTheme as ThemeType);
    if (savedUnavail) setUnavailabilities(JSON.parse(savedUnavail));
  }, []);

  useEffect(() => {
    localStorage.setItem('evo_tasks', JSON.stringify(tasks));
    localStorage.setItem('evo_theme', theme);
    localStorage.setItem('evo_unavailabilities', JSON.stringify(unavailabilities));

    const currentThemeData = THEMES[theme];
    document.body.style.backgroundColor = currentThemeData.hex;

    if (theme === 'dark') {
      document.body.classList.add('dark');
    } else {
      document.body.classList.remove('dark');
    }
  }, [tasks, theme, unavailabilities]);

  const addTask = (taskData: any) => {
    const newTask: Task = {
      ...taskData,
      id: Math.random().toString(36).substr(2, 9),
      createdAt: Date.now(),
      actualMinutes: 0
    };
    setTasks([...tasks, newTask]);
    setIsTaskModalOpen(false);
  };

  const updateTask = (id: string, updates: Partial<Task>) => {
    setTasks(tasks.map(t => {
      if (t.id === id) {
        const isNowDone = updates.status === TaskStatus.DONE && t.status !== TaskStatus.DONE;
        return { 
          ...t, 
          ...updates, 
          completedAt: isNowDone ? Date.now() : (updates.status === TaskStatus.TODO ? undefined : t.completedAt)
        };
      }
      return t;
    }));
    setIsTaskModalOpen(false);
    setEditingTask(undefined);
  };

  const addUnavailability = (unavail: Omit<Unavailability, 'id'>) => {
    setUnavailabilities([...unavailabilities, { ...unavail, id: Math.random().toString(36).substr(2, 9) }]);
  };

  const deleteUnavailability = (id: string) => {
    setUnavailabilities(unavailabilities.filter(u => u.id !== id));
  };

  const currentTheme = THEMES[theme];

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <Dashboard 
            tasks={tasks} 
            theme={theme} 
            unavailabilities={unavailabilities}
            onAddTask={() => setIsTaskModalOpen(true)} 
            onUpdateTask={updateTask}
            onAddUnavailability={addUnavailability}
            onDeleteUnavailability={deleteUnavailability}
          />
        );
      case 'tasks':
        return <TodoList tasks={tasks} onUpdateTask={updateTask} onDeleteTask={(id) => setTasks(tasks.filter(t => t.id !== id))} onEditTask={(t) => { setEditingTask(t); setIsTaskModalOpen(true); }} onAddTask={() => setIsTaskModalOpen(true)} theme={theme} />;
      case 'matrix':
        return <EisenhowerMatrix tasks={tasks} onUpdateTask={updateTask} theme={theme} />;
      case 'planning':
        return <SmartPlanning tasks={tasks} unavailabilities={unavailabilities} theme={theme} />;
      case 'focus':
        return <Pomodoro theme={theme} tasks={tasks} onUpdateTask={updateTask} />;
      case 'stats':
        return <ProgressTracking tasks={tasks} theme={theme} />;
      default:
        return <Dashboard tasks={tasks} theme={theme} unavailabilities={unavailabilities} onAddTask={() => setIsTaskModalOpen(true)} onUpdateTask={updateTask} onAddUnavailability={addUnavailability} onDeleteUnavailability={deleteUnavailability} />;
    }
  };

  const navItems = [
    { id: 'dashboard', label: 'Accueil', icon: LayoutDashboard },
    { id: 'tasks', label: 'Tâches', icon: CheckSquare },
    { id: 'matrix', label: 'Priorités', icon: Grid2X2 },
    { id: 'planning', label: 'Planning IA', icon: CalendarDays },
    { id: 'focus', label: 'Focus', icon: Timer },
    { id: 'stats', label: 'Analyses', icon: BarChart3 },
  ];

  return (
    <div className={`min-h-screen flex flex-col md:flex-row ${currentTheme.bg} ${currentTheme.text} transition-all duration-500`}>
      <aside className={`hidden md:flex flex-col w-64 ${currentTheme.card} border-r ${currentTheme.accent} h-screen sticky top-0 transition-colors duration-500`}>
        <div className="p-6 flex items-center gap-3">
          <div className={`w-10 h-10 rounded-xl ${currentTheme.primary} flex items-center justify-center text-white shadow-lg shadow-primary/20`}>
            <BarChart3 size={24} />
          </div>
          <span className="text-2xl font-bold tracking-tight">Evo</span>
        </div>
        <nav className="flex-1 px-4 space-y-2 mt-4">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-300 ${
                activeTab === item.id 
                ? `${currentTheme.primary} text-white shadow-lg` 
                : `hover:bg-black/5 text-slate-500 dark:text-slate-400`
              }`}
            >
              <item.icon size={20} />
              <span className="font-medium">{item.label}</span>
            </button>
          ))}
        </nav>
        <div className="p-4 border-t border-slate-100 dark:border-slate-800">
          <div className="flex justify-between items-center mb-4 px-2">
            <span className="text-[10px] font-black text-slate-400 tracking-widest uppercase">Thèmes</span>
            <div className="flex gap-1.5">
              {(Object.keys(THEMES) as ThemeType[]).map((t) => (
                <button
                  key={t}
                  onClick={() => setTheme(t)}
                  className={`w-6 h-6 rounded-full border-2 transition-transform hover:scale-110 ${theme === t ? 'border-slate-400 ring-2 ring-offset-2 ring-slate-200' : 'border-transparent'} ${THEMES[t].primary}`}
                />
              ))}
            </div>
          </div>
        </div>
      </aside>

      <nav className={`md:hidden fixed bottom-0 left-0 right-0 z-50 ${currentTheme.card} border-t ${currentTheme.accent} px-2 py-3 flex justify-around shadow-2xl`}>
        {navItems.map((item) => (
          <button key={item.id} onClick={() => setActiveTab(item.id)} className={`flex flex-col items-center gap-1 p-2 ${activeTab === item.id ? currentTheme.secondary : 'text-slate-400'}`}>
            <item.icon size={20} />
            <span className="text-[10px] font-medium">{item.label}</span>
          </button>
        ))}
      </nav>

      <main className="flex-1 p-4 md:p-8 pb-24 md:pb-8 max-w-7xl mx-auto w-full transition-all duration-500">
        <header className="flex justify-between items-center mb-8">
          <div>
            <h1 className="text-2xl font-black tracking-tight">Bonjour ! 👋</h1>
            <p className="opacity-60 text-sm font-medium">Prêt pour une session de travail efficace ?</p>
          </div>
          <button 
            onClick={() => setIsTaskModalOpen(true)}
            className={`${currentTheme.primary} text-white px-5 py-3 rounded-2xl shadow-xl flex items-center gap-2 hover:scale-105 active:scale-95 transition-all`}
          >
            <Plus size={20} /> <span className="hidden sm:inline font-bold">Nouvelle Tâche</span>
          </button>
        </header>

        {renderContent()}

        {isTaskModalOpen && (
          <TaskModal 
            theme={theme}
            task={editingTask}
            onClose={() => { setIsTaskModalOpen(false); setEditingTask(undefined); }}
            onSubmit={editingTask ? (data) => updateTask(editingTask.id, data) : addTask}
          />
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Task, TaskStatus, ThemeType, TaskPriority, EisenhowerQuadrant, Unavailability } from '../types';
import { THEMES } from '../constants';
import { CheckCircle2, Clock, Calendar, TrendingUp, Plus, Target, X, Clock3 } from 'lucide-react';

interface DashboardProps {
  tasks: Task[];
  theme: ThemeType;
  unavailabilities: Unavailability[];
  onAddTask: (task: any) => void;
  onUpdateTask: (id: string, updates: any) => void;
  onAddUnavailability: (unavail: Omit<Unavailability, 'id'>) => void;
  onDeleteUnavailability: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ 
  tasks, 
  theme, 
  unavailabilities, 
  onAddTask, 
  onAddUnavailability, 
  onDeleteUnavailability 
}) => {
  const currentTheme = THEMES[theme];

  const [newUnavail, setNewUnavail] = useState({ day: 'Lundi', startTime: '08:00', endTime: '12:00', reason: 'Cours' });

  const completedTasks = tasks.filter(t => t.status === TaskStatus.DONE);
  const pendingTasks = tasks.filter(t => t.status !== TaskStatus.DONE);
  const totalEstimated = tasks.reduce((acc, curr) => acc + curr.estimatedMinutes, 0);
  const progressPercentage = tasks.length > 0 ? Math.round((completedTasks.length / tasks.length) * 100) : 0;

  const days = ['Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi', 'Dimanche'];

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      {/* Stats Overview */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard label="Tâches terminées" value={completedTasks.length.toString()} icon={CheckCircle2} color="text-green-500" theme={theme} />
        <StatCard label="Tâches en attente" value={pendingTasks.length.toString()} icon={Clock} color="text-orange-500" theme={theme} />
        <StatCard label="Temps total estimé" value={`${Math.floor(totalEstimated / 60)}h ${totalEstimated % 60}m`} icon={Calendar} color="text-blue-500" theme={theme} />
        <StatCard label="Score de Focus" value={`${progressPercentage}%`} icon={TrendingUp} color="text-purple-500" theme={theme} />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-8">
          {/* Main Progression Card */}
          <div className={`${currentTheme.card} rounded-[2.5rem] p-8 border ${currentTheme.accent} shadow-xl shadow-black/5 flex flex-col items-center justify-center min-h-[350px] transition-colors duration-500`}>
             <div className="relative w-56 h-56 flex items-center justify-center">
                <svg className="w-full h-full transform -rotate-90 absolute inset-0" viewBox="0 0 192 192">
                  <circle cx="96" cy="96" r="80" stroke="currentColor" strokeWidth="12" fill="transparent" className="opacity-10" />
                  <circle cx="96" cy="96" r="80" stroke="currentColor" strokeWidth="12" fill="transparent" strokeDasharray={2 * Math.PI * 80} strokeDashoffset={2 * Math.PI * 80 * (1 - progressPercentage / 100)} strokeLinecap="round" className={`${currentTheme.secondary} transition-all duration-1000 ease-out`} />
                </svg>
                <div className="flex flex-col items-center justify-center z-10">
                  <Target size={32} className={`${currentTheme.secondary} mb-1 opacity-20`} />
                  <span className="text-5xl font-black leading-none tracking-tighter tabular-nums">{progressPercentage}%</span>
                  <span className="text-[10px] opacity-40 font-bold uppercase tracking-widest mt-2">Objectif</span>
                </div>
             </div>
             <div className="mt-8 text-center">
                <h3 className="text-xl font-bold mb-2">Ton objectif du jour</h3>
                <p className="opacity-50 max-w-xs mx-auto text-sm font-medium italic">
                  {progressPercentage === 100 ? "Félicitations ! 🏆" : progressPercentage > 50 ? "Presque ! 💪" : "Une étape à la fois. 🚀"}
                </p>
             </div>
          </div>

          {/* Unavailabilities Management */}
          <div className={`${currentTheme.card} rounded-[2.5rem] p-8 border ${currentTheme.accent} shadow-xl shadow-black/5 transition-colors duration-500`}>
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-bold flex items-center gap-2">
                <Clock3 className={currentTheme.secondary} size={24} /> Mon Emploi du Temps
              </h3>
              <p className="text-[10px] font-black opacity-30 uppercase tracking-widest">IA Exclusion Zone</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="bg-black/5 dark:bg-white/5 p-6 rounded-3xl space-y-4">
                <div className="space-y-3">
                  <select 
                    value={newUnavail.day} 
                    onChange={(e) => setNewUnavail({...newUnavail, day: e.target.value})}
                    className="w-full bg-white dark:bg-slate-800 border-none rounded-xl px-4 py-2 text-sm outline-none focus:ring-2 ring-blue-400"
                  >
                    {days.map(d => <option key={d} value={d}>{d}</option>)}
                  </select>
                  <div className="flex gap-2">
                    <input type="time" value={newUnavail.startTime} onChange={(e) => setNewUnavail({...newUnavail, startTime: e.target.value})} className="flex-1 bg-white dark:bg-slate-800 border-none rounded-xl px-4 py-2 text-sm outline-none focus:ring-2 ring-blue-400" />
                    <input type="time" value={newUnavail.endTime} onChange={(e) => setNewUnavail({...newUnavail, endTime: e.target.value})} className="flex-1 bg-white dark:bg-slate-800 border-none rounded-xl px-4 py-2 text-sm outline-none focus:ring-2 ring-blue-400" />
                  </div>
                  <input type="text" placeholder="Raison (Cours, Sport...)" value={newUnavail.reason} onChange={(e) => setNewUnavail({...newUnavail, reason: e.target.value})} className="w-full bg-white dark:bg-slate-800 border-none rounded-xl px-4 py-2 text-sm outline-none focus:ring-2 ring-blue-400" />
                  <button onClick={() => onAddUnavailability(newUnavail)} className={`w-full ${currentTheme.primary} text-white font-bold py-3 rounded-xl text-sm flex items-center justify-center gap-2 shadow-lg hover:brightness-110 active:scale-95 transition-all`}>
                    <Plus size={16} /> Ajouter le blocage
                  </button>
                </div>
              </div>

              <div className="space-y-3 overflow-y-auto max-h-[250px] pr-2 custom-scrollbar">
                {unavailabilities.length === 0 ? (
                  <div className="h-full flex flex-col items-center justify-center border-2 border-dashed border-black/5 dark:border-white/5 rounded-3xl p-6 text-center">
                    <p className="text-xs opacity-40 italic">Aucun créneau bloqué.</p>
                  </div>
                ) : (
                  unavailabilities.map(u => (
                    <div key={u.id} className="flex items-center justify-between p-4 bg-white/50 dark:bg-slate-800/50 rounded-2xl border border-black/5 group hover:border-black/10 transition-colors">
                      <div>
                        <p className="text-xs font-bold">{u.day} • {u.reason}</p>
                        <p className="text-[10px] opacity-50 font-medium">{u.startTime} - {u.endTime}</p>
                      </div>
                      <button onClick={() => onDeleteUnavailability(u.id)} className="p-1.5 text-red-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity">
                        <X size={16} />
                      </button>
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>
        </div>

        {/* Quick Add Section */}
        <div className="flex flex-col gap-4">
          <div className={`${currentTheme.card} rounded-[2rem] p-6 border ${currentTheme.accent} shadow-xl shadow-black/5 transition-colors duration-500`}>
            <h3 className="font-bold text-lg mb-4 flex items-center gap-2">
              <Plus size={20} className={currentTheme.secondary} /> Ajout Rapide
            </h3>
            <form onSubmit={(e) => {
              e.preventDefault();
              const form = e.target as HTMLFormElement;
              const input = form.elements.namedItem('taskTitle') as HTMLInputElement;
              if (input.value.trim()) {
                onAddTask({ title: input.value, status: TaskStatus.TODO, priority: TaskPriority.MEDIUM, difficulty: 'medium', quadrant: EisenhowerQuadrant.DO_FIRST, estimatedMinutes: 30 });
                form.reset();
              }
            }} className="space-y-4">
              <input name="taskTitle" type="text" placeholder="Quelle est la prochaine étape ?" className="w-full bg-black/5 dark:bg-white/5 border-none rounded-2xl px-4 py-4 text-sm focus:ring-2 ring-lime-400 outline-none transition-all" />
              <button className={`w-full ${currentTheme.primary} text-white font-bold py-4 rounded-2xl shadow-xl shadow-primary/20 hover:brightness-110 active:scale-95 transition-all`}>Ajouter à ma liste</button>
            </form>
          </div>
          <div className={`${currentTheme.card} rounded-[2rem] p-6 border ${currentTheme.accent} shadow-xl shadow-black/5 transition-colors duration-500`}>
            <h3 className="font-bold text-lg mb-2 flex items-center gap-2">🤖 Evo AI</h3>
            <p className="text-sm opacity-60 leading-relaxed italic font-medium">
              "Pense à bloquer tes heures de sommeil pour que je puisse générer un planning réaliste !"
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

const StatCard: React.FC<{ label: string; value: string; icon: any; color: string; theme: ThemeType }> = ({ label, value, icon: Icon, color, theme }) => {
