            <p className="text-sm opacity-60 leading-relaxed italic font-bold">
              "Le succès n'est pas un sprint, c'est une suite de petites habitudes. Bloque tes heures de sommeil, c'est ta priorité n°1."
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

