import React, { useState, useEffect, useRef } from 'react';
import { Task, TaskStatus, ThemeType } from '../../types';
import { THEMES } from '../../constants';
import { Play, Pause, RotateCcw, Coffee, Brain, Bell, Volume2, Waves, Coffee as CoffeeIcon, Library } from 'lucide-react';

interface PomodoroProps {
  theme: ThemeType;
  tasks: Task[];
  onUpdateTask: (id: string, updates: Partial<Task>) => void;
}

const Pomodoro: React.FC<PomodoroProps> = ({ theme, tasks, onUpdateTask }) => {
  const currentTheme = THEMES[theme];
  const [timeLeft, setTimeLeft] = useState(25 * 60);
  const [isActive, setIsActive] = useState(false);
  const [mode, setMode] = useState<'work' | 'break'>('work');
  const [selectedTask, setSelectedTask] = useState<string | null>(null);
  const [ambiance, setAmbiance] = useState<'none' | 'rain' | 'cafe' | 'library'>('none');

  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    if (isActive && timeLeft > 0) {
      timerRef.current = setInterval(() => {
        setTimeLeft(prev => prev - 1);
      }, 1000);
    } else if (timeLeft === 0) {
      handleTimerComplete();
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [isActive, timeLeft]);

  const handleTimerComplete = () => {
    setIsActive(false);
    if (mode === 'work') {
      if (selectedTask) {
        const task = tasks.find(t => t.id === selectedTask);
        if (task) {
          onUpdateTask(selectedTask, { actualMinutes: (task.actualMinutes || 0) + 25 });
        }
      }
      setMode('break');
      setTimeLeft(5 * 60);
    } else {
      setMode('work');
      setTimeLeft(25 * 60);
    }
  };

  const toggleTimer = () => setIsActive(!isActive);
  const resetTimer = () => {
    setIsActive(false);
    setTimeLeft(mode === 'work' ? 25 * 60 : 5 * 60);
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const progress = (mode === 'work' ? 25 * 60 - timeLeft : 5 * 60 - timeLeft) / (mode === 'work' ? 25 * 60 : 5 * 60) * 100;

  const ambiances = [
    { id: 'none', icon: Volume2, label: 'Silence' },
    { id: 'rain', icon: Waves, label: 'Pluie' },
    { id: 'cafe', icon: CoffeeIcon, label: 'Café' },
    { id: 'library', icon: Library, label: 'Bibliothèque' }
  ];

  return (
    <div className="flex flex-col items-center justify-center space-y-12 py-10 animate-in fade-in scale-95 duration-500">
      <div className="flex gap-4 p-1.5 bg-black/5 dark:bg-white/5 rounded-2xl border border-black/5 shadow-inner">
        <button 
          onClick={() => { setMode('work'); setTimeLeft(25 * 60); setIsActive(false); }}
          className={`flex items-center gap-2 px-8 py-3 rounded-xl text-sm font-black transition-all ${mode === 'work' ? `${currentTheme.button} shadow-lg scale-105` : 'text-slate-500 opacity-60 hover:opacity-100'}`}
        >
          <Brain size={18} /> FOCUS
        </button>
        <button 
          onClick={() => { setMode('break'); setTimeLeft(5 * 60); setIsActive(false); }}
          className={`flex items-center gap-2 px-8 py-3 rounded-xl text-sm font-black transition-all ${mode === 'break' ? `${currentTheme.button} shadow-lg scale-105` : 'text-slate-500 opacity-60 hover:opacity-100'}`}
        >
          <Coffee size={18} /> PAUSE
        </button>
      </div>

      <div className="relative flex items-center justify-center">
        <div className="w-72 h-72 md:w-96 md:h-96 rounded-full border-[16px] border-black/5 dark:border-white/5 flex items-center justify-center relative overflow-hidden shadow-2xl">
            <div 
              className={`absolute bottom-0 w-full transition-all duration-1000 ease-linear ${currentTheme.primary} opacity-10`} 
              style={{ height: `${progress}%` }} 
            />
            <div className="text-7xl md:text-9xl font-black tracking-tighter tabular-nums z-10 transition-all">
                {formatTime(timeLeft)}
            </div>
        </div>
      </div>

      <div className="flex gap-8 items-center">
        <button onClick={resetTimer} className="p-5 rounded-full bg-black/5 text-slate-400 hover:text-slate-600 hover:scale-110 transition-all">
          <RotateCcw size={32} />
        </button>
        <button 
          onClick={toggleTimer}
          className={`p-10 rounded-full ${currentTheme.button} shadow-[0_20px_50px_rgba(0,0,0,0.1)] transform transition-all active:scale-90 hover:scale-105 flex items-center justify-center`}
        >
          {isActive ? <Pause size={48} fill="currentColor" strokeWidth={3} /> : <Play size={48} fill="currentColor" strokeWidth={3} />}
        </button>
        <button className="p-5 rounded-full bg-black/5 text-slate-400 hover:text-slate-600 hover:scale-110 transition-all">
          <Bell size={32} />
        </button>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 w-full max-w-2xl px-4">
        {ambiances.map(a => (
          <button
            key={a.id}
            onClick={() => setAmbiance(a.id as any)}
