                />
                <Bar dataKey="completed" radius={[6, 6, 0, 0]}>
                  {weeklyData.map((entry, index) => (
                    // Fix: updated theme check to 'emerald' and set emerald-500 color (#10b981)
                    <Cell key={`cell-${index}`} fill={entry.completed >= entry.goal ? (theme === 'emerald' ? '#10b981' : '#3b82f6') : '#cbd5e1'} />
